/**
 * 页面内「地图设置」→ 配置文件的写回通道（只在开发服务器上可用）。
 *
 * 站点是纯静态的，浏览器改不了磁盘文件；开发服务器挂了一个本地接口
 * （见 `vite-plugin-museum-config.ts`），页面上就能把选定的默认视野/点位**直接落盘**，
 * 不用再"导出片段 → 手工粘贴"。生产环境（`vite preview` / 静态托管）没有这个接口，
 * 探测失败后页面自动退回"存本机 + 导出片段"，不会报错。
 */
import { resolveAssetUrl } from './loadConfig';

export const CONFIG_WRITER_PATH = '__museum/config';

export interface WriteResult {
  ok: boolean;
  path?: string;
  changed?: string[];
  skipped?: string[];
  error?: string;
}

/** 开发服务器是否挂了这个接口。 */
export async function probeConfigWriter(fetcher: typeof fetch = fetch): Promise<boolean> {
  try {
    const response = await fetcher(resolveAssetUrl(CONFIG_WRITER_PATH), { method: 'GET' });
    if (!response.ok) return false;
    const body = await response.json() as { writable?: boolean };
    return body?.writable === true;
  } catch {
    return false;
  }
}

/** 把片段交给开发服务器写进 config/museum.json。 */
export async function writeConfigDefaults(
  payload: unknown,
  fetcher: typeof fetch = fetch,
): Promise<WriteResult> {
  try {
    const response = await fetcher(resolveAssetUrl(CONFIG_WRITER_PATH), {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify(payload),
    });
    const body = await response.json() as WriteResult;
    if (!response.ok || !body?.ok) return { ok: false, error: body?.error ?? `HTTP ${response.status}` };
    return body;
  } catch (error) {
    return { ok: false, error: error instanceof Error ? error.message : String(error) };
  }
}
