import { Check, Crosshair, Download, EyeOff, Minus, Plus, RotateCcw, Save, Settings, Trash2, X } from 'lucide-react';
import { Suspense, lazy, useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useNavigate, useParams, useSearchParams } from 'react-router-dom';
import { useMuseumConfig } from '../../config/ConfigProvider';
import { probeConfigWriter, writeConfigDefaults } from '../../config/configWriter';
import { resolveAssetUrl } from '../../config/loadConfig';
import {
  EMPTY_OVERRIDES, clearOverrides, loadOverrides, saveOverrides,
  type MapOverrides, type Overrides,
} from '../../config/overrides';
import type { MapConfig, MapPointConfig } from '../../config/schema';
import { lngLatFromNormalized, normalizeLngLat } from '../../shared/geo';
import { reloadPage } from '../../shared/reload';
import {
  DRILL_DURATION_MS, DRILL_SCALE, IDENTITY_TRANSFORM, IMAGE_SCALE_LIMITS, TILE_SIZE, centerOnPoint, clampScale,
  clampTransform, fitContain, fitCover, lngToMercator, mercatorAspect, normalizedFromScreen,
  scaleForSpanMeters, scaleLimitsFor, spanMetersOf, tilesForViewport, visibleRect, zoomAtPoint, zoomForBounds,
  type MapTransform, type ScaleLimits, type Size,
} from './mapNavigation';
import './map.css';

const EMPTY_SIZE: Size = { width: 0, height: 0 };

/** 瓦片取不到时的重试次数与起始退避（每次 ×2）。见 `TileImage` 的注释。 */
const TILE_RETRIES = 3;
const TILE_RETRY_BASE_MS = 600;

/**
 * 一张瓦片：失败**必须重试**，不能像原来那样 `visibility: hidden` 一了百了。
 *
 * 上线反馈"全景漫游时 iOS 上瓦片加载不出来"，根因就在这条路径上：
 * 手机上一屏要几十上百张瓦片（高分屏还要多要一层），叠加场地模型/视频/720yun iframe 之后，
 * 同一 host 的连接数与内存都被挤爆，**部分瓦片请求会失败或被打断**。
 * 旧实现一旦失败就把这张图永久隐藏 —— 于是地图上留下若干空白块，而且再也不恢复。
 * iOS 的连接受限与内存回收比桌面激进得多，所以在手机上尤其明显。
 *
 * 这里加三件事：
 * 1. 失败后退避重试（600ms / 1.2s / 2.4s），重试时带 `?r=N` 绕过失败响应/缓存；
 * 2. `cache: 'no-store'`：iOS 偶尔会把失败结果也缓存住，重试同一 URL 拿到的还是失败；
 * 3. 整轮都失败才隐藏（避免碎裂图标），并保留原始 `src` 以便下次重渲染时再试。
 */
function TileImage({ url, className, style }: { url: string; className: string; style: React.CSSProperties }) {
  const [attempt, setAttempt] = useState(0);
  const [hidden, setHidden] = useState(false);

  // 换 URL（缩放/平移后是另一批瓦片）时重置重试状态：新瓦片值得从头试。
  useEffect(() => { setAttempt(0); setHidden(false); }, [url]);

  const src = attempt === 0 ? url : `${url}${url.includes('?') ? '&' : '?'}r=${attempt}`;
  return (
    <img
      className={className}
      src={src}
      alt=""
      draggable={false}
      // 天地图等瓦片服务对来源敏感：不带 referrer 比带更稳，也避免第三方拿到院区访问日志。
      referrerPolicy="no-referrer"
      style={hidden ? { ...style, visibility: 'hidden' } : style}
      onError={() => {
        if (attempt >= TILE_RETRIES) {
          setHidden(true);
          return;
        }
        const delay = TILE_RETRY_BASE_MS * 2 ** attempt;
        window.setTimeout(() => setAttempt(value => value + 1), delay);
      }}
    />
  );
}

/** 移动超过这个像素才算拖动，否则保留为点击（否则标记按钮永远点不到）。 */
const DRAG_THRESHOLD = 6;
/** 从全景页回到地图时，以这个倍数把目标点位推到画面中心。 */
const FOCUS_SCALE = 2.4;
/** 瓦片模式下用于推算层级的虚拟底图宽度。 */
const TILE_BASE_PX = 1024;
/** 点标记进入全景时「推近」的目标倍数与时长：先放大再压暗，切过去后由全景页淡出。 */
const ENTER_SCALE = 9;
const ENTER_DURATION_MS = 620;
/**
 * 「地图设置」**默认永远是隐藏的**：连点「回到默认视野」这么多次才出现。
 * 解锁状态**只存在内存里**（不写 localStorage）：每次打开/刷新页面都回到隐藏状态，
 * 这样访客和现场设备都不会看到这个入口，布展的人每次要用时点五下即可。
 */
const SETTINGS_UNLOCK_CLICKS = 5;
/** 早期版本把解锁状态写在了这里，启动时清一次，免得残留的标记让人以为"默认没藏住"。 */
const LEGACY_SETTINGS_UNLOCK_KEY = 'museum.map-settings.unlocked';

function targetRoute(point: MapPointConfig): string {
  switch (point.target.kind) {
    case 'map': return `/map/${point.target.id}`;
    case 'panorama': return `/panorama/${point.target.id}`;
    default: return `/devices/${point.target.id}`;
  }
}

function markerLabel(point: MapPointConfig): string {
  if (point.target.kind === 'panorama') return `前往${point.label}`;
  if (point.target.kind === 'map') return `进入${point.label}`;
  return `查看${point.label}`;
}

const fixed = (value: number, digits = 6) => value.toFixed(digits);

/**
 * 全景漫游作为**地图页的一层**渲染（不再是一个独立栏目）。
 * 懒加载：不进漫游就不会下载它的代码。
 */
const PanoramaOverlay = lazy(() => import('../panorama/PanoramaPage').then(module => ({ default: module.PanoramaPage })));

export function MapPage({ active = true }: { active?: boolean } = {}) {
  const { mapId, pointId: roamId } = useParams();
  const [search] = useSearchParams();
  const focusId = search.get('focus');
  const navigate = useNavigate();
  const { repository } = useMuseumConfig();

  const map: MapConfig | undefined = (mapId ? repository.getMap(mapId) : undefined) ?? repository.getRootMap();
  const path = useMemo(() => (map ? repository.getMapPath(map.id) : []), [map, repository]);

  const stageRef = useRef<HTMLDivElement>(null);
  const drillTimer = useRef<number | null>(null);
  const [container, setContainer] = useState<Size>(EMPTY_SIZE);
  /**
   * 设备像素比。选瓦片层级时必须考虑它：源图是 256px，若只按 CSS 像素选层级，
   * 在 DPR 2/3 的手机上同一张图会被摊到 400+ 设备像素上，放大 1.6~1.7 倍 → 发虚。
   * 窗口在不同缩放的显示器之间移动时 DPR 会变并触发 resize，所以跟着更新。
   */
  const [pixelRatio, setPixelRatio] = useState(() => (typeof window === 'undefined' ? 1 : window.devicePixelRatio || 1));
  const [natural, setNatural] = useState<Size>(EMPTY_SIZE);
  const [transform, setTransform] = useState<MapTransform>(IDENTITY_TRANSFORM);
  const [dragging, setDragging] = useState(false);
  const [drillingId, setDrillingId] = useState<string | null>(null);
  const [settingsOpen, setSettingsOpen] = useState(false);
  const [settingsUnlocked, setSettingsUnlocked] = useState(false);
  const resetClicks = useRef(0);
  /** 开发服务器能不能写配置文件；不能写就退回"存本机 + 导出片段"。 */
  const [canWriteConfig, setCanWriteConfig] = useState(false);
  const [saving, setSaving] = useState(false);
  /** 正在“推进”进入的点位：底图放大 + 压暗，随后跳转。 */
  const [enteringId, setEnteringId] = useState<string | null>(null);
  /** 进漫游前的视野；关掉漫游时原样还回去（漫游只是盖在地图上的一层）。 */
  const preRoamTransform = useRef<MapTransform | null>(null);
  /** 正在“点选武高所位置”，此时点地图是放标记而不是进全景。 */
  const [picking, setPicking] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  /** 页面内改动过的设置（先在本机生效，导出后可固化进 museum.json）。 */
  const [draft, setDraft] = useState<Overrides>(() => loadOverrides());

  const basemap = map?.basemap;
  // 瓦片底图没有天然尺寸，按经纬度范围的墨卡托宽高比给一个等价尺寸，
  // 这样标记定位、平移、钳制等逻辑与静态图完全共用。
  const tileSize = useMemo<Size>(() => {
    if (basemap?.kind !== 'tiles') return EMPTY_SIZE;
    return { width: TILE_BASE_PX, height: TILE_BASE_PX / mercatorAspect(basemap.bounds) };
  }, [basemap]);
  const naturalSize = basemap?.kind === 'tiles' ? tileSize : natural;

  // 瓦片底图用 cover：铺满舞台，左右（宽屏下）或上下（竖屏下）不留空白；静态图仍用 contain，保证整幅可见。
  const { box, origin } = useMemo(
    () => (basemap?.kind === 'tiles' ? fitCover(naturalSize, container) : fitContain(naturalSize, container)),
    [basemap?.kind, naturalSize, container],
  );
  const ready = box.width > 0 && box.height > 0;
  /** 整幅范围刚好铺满时的瓦片层级；initialView.zoom 与缩放倍数都以它为基准。 */
  const baseZoom = useMemo(
    () => (basemap?.kind === 'tiles' && ready ? zoomForBounds(basemap.bounds, box.width) : 0),
    [basemap, box.width, ready],
  );
  /**
   * 缩放上下限。瓦片底图的上限取「正好能放大到 maxZoom」，
   * 因此从全域到最深一层可以一路自由缩放，不再分两级。
   */
  const limits = useMemo<ScaleLimits>(
    () => (basemap?.kind === 'tiles' && ready
      ? scaleLimitsFor(basemap.minZoom, basemap.maxZoom, baseZoom)
      : IMAGE_SCALE_LIMITS),
    [basemap, baseZoom, ready],
  );
  const zoom = useMemo(() => {
    if (basemap?.kind !== 'tiles' || !ready) return 0;
    const base = baseZoom + Math.round(Math.log2(transform.scale));
    /*
     * 让"一张瓦片"落在约 256 个**设备像素**上——源图就是 256px，此时 1:1 最清晰。
     *
     * 只有在**确实会被拉伸**时才升一层：判据从 `log2(倍数)` 取整（≥1.0 就升）收紧为 ≥1.15。
     * 实测差别很大：DPR 3 的手机上旧判据会从 0.79 一路升到 1.58（源图被摊到 476 设备像素），
     * 白白多要一层（**每屏瓦片数 ×4**）；新判据停在 0.79（源图 256px 缩到 202 设备像素，
     * 略缩不糊）。手机上瓦片请求数、解码内存都是 iOS 最容易崩的地方，这一层省下来很值。
     */
    const spanX = lngToMercator(basemap.bounds.east) - lngToMercator(basemap.bounds.west);
    const tileLayoutPx = box.width / (2 ** base * spanX);
    const tileDevicePx = tileLayoutPx * transform.scale * pixelRatio;
    const stretch = Number.isFinite(tileDevicePx) && tileDevicePx > 0 ? tileDevicePx / TILE_SIZE : 1;
    const crispStep = stretch >= 1.15 ? Math.ceil(Math.log2(stretch)) : Math.floor(Math.log2(stretch));
    return Math.max(basemap.minZoom, Math.min(basemap.maxZoom, base + crispStep));
  }, [baseZoom, basemap, box.width, pixelRatio, ready, transform.scale]);
  /**
   * 实际用来选瓦片的层级：**稳定 140ms 之后才生效**。
   *
   * 缩放/下钻动画期间每一帧都会算出新的层级，直接跟着渲染的话，同一屏会反复请求好几套瓦片
   * （实测初始化一次就打了 48 个瓦片请求，而屏幕上只要 12 张）。手机上这会把同一 host 的连接数
   * 挤爆 —— 部分请求失败 → 瓦片空白，正是"iOS 上加载不出来"的放大器。
   * 停手后立刻生效，用户只慢 140ms，看不出差别。
   */
  const [settledZoom, setSettledZoom] = useState(0);
  useEffect(() => {
    if (!zoom) return;
    const timer = window.setTimeout(() => setSettledZoom(zoom), 140);
    return () => window.clearTimeout(timer);
  }, [zoom]);
  const tiles = useMemo(() => {
    if (basemap?.kind !== 'tiles' || !ready || !settledZoom) return [];
    // 在线 HTTPS 模板原样保留；其他配置的相对路径仍由 BASE_URL 解析。
    const view = visibleRect(transform, box, container, origin);
    const base = tilesForViewport(basemap.bounds, settledZoom, view, resolveAssetUrl(basemap.urlTemplate));
    if (!basemap.overlayTemplate) return base;
    // 标注层与底图同范围同层级，叠在上面；用不同 key 前缀避免 React key 冲突。
    const overlay = tilesForViewport(basemap.bounds, settledZoom, view, resolveAssetUrl(basemap.overlayTemplate));
    return [...base, ...overlay.map(tile => ({ ...tile, key: `overlay-${tile.key}`, overlay: true }))];
  }, [basemap, box, container, ready, settledZoom, transform, origin]);

  // 探测"能否直接写回配置文件"（只有开发服务器会挂这个接口）。
  useEffect(() => {
    let active = true;
    void probeConfigWriter().then(value => { if (active) setCanWriteConfig(value); });
    // 清掉旧版本留下的"解锁状态"残留，免得让人以为默认没藏住。
    try { window.localStorage.removeItem(LEGACY_SETTINGS_UNLOCK_KEY); } catch { /* 隐私模式忽略 */ }
    return () => { active = false; };
  }, []);

  // 容器尺寸：手机旋转、平板分栏都会改变它。
  useEffect(() => {
    const stage = stageRef.current;
    if (!stage) return;
    const measure = () => {
      const width = stage.clientWidth;
      const height = stage.clientHeight;
      /*
       * 本页在「全景漫游」这个常驻槽位里：切到别的栏目时会加 hidden，舞台瞬间量到 0×0，
       * 而 container 一旦变成 0，下面的 box/ready/transform 会连锁重置——切回来视野就丢了
       * （等于白常驻）。所以 0 尺寸一律当成"没量到"，保留上一次真实尺寸。
       */
      if (width <= 0 || height <= 0) return;
      setContainer(current => (current.width === width && current.height === height ? current : { width, height }));
    };
    measure();
    if (typeof ResizeObserver === 'undefined') return;
    const observer = new ResizeObserver(measure);
    observer.observe(stage);
    return () => observer.disconnect();
  }, []);

  // DPR 可能因为窗口移到另一块屏幕而改变。
  useEffect(() => {
    const sync = () => setPixelRatio(window.devicePixelRatio || 1);
    sync();
    window.addEventListener('resize', sync);
    return () => window.removeEventListener('resize', sync);
  }, []);

  useEffect(() => () => { if (drillTimer.current !== null) window.clearTimeout(drillTimer.current); }, []);
  useEffect(() => {
    if (!notice) return;
    const timer = window.setTimeout(() => setNotice(null), 2600);
    return () => window.clearTimeout(timer);
  }, [notice]);

  /**
   * 进入某一级时的落点，优先级：
   *   1) URL 里的 ?focus=<点位或目标 id>（从全景页「在地图查看位置」回来）；
   *   2) 配置的 initialView（`zoom` 指定瓦片层级，`scale` 指定倍数）；
   *   3) 底图中心、1 倍。
   * 先比目标略微放大再回落，形成“推进来”的层次感。
   */
  const settle = useMemo(() => {
    const focused = focusId
      ? map?.points.find(point => point.id === focusId || point.target.id === focusId)
      : undefined;
    if (focused) return { point: { x: focused.x, y: focused.y }, zoom: null, scale: FOCUS_SCALE, spanMeters: null };
    if (map?.basemap.kind === 'tiles' && map.initialView) {
      const view = map.initialView;
      return {
        point: normalizeLngLat(view.lng, view.lat, map.basemap.bounds),
        zoom: view.zoom ?? null,
        scale: view.scale,
        spanMeters: view.spanMeters ?? null,
      };
    }
    return { point: { x: 0.5, y: 0.5 }, zoom: null, scale: 1, spanMeters: null };
  }, [focusId, map]);

  /**
   * 初始/默认视野的最终倍数。优先级：按横向跨度 > 按瓦片层级 > 按倍数。
   * 按跨度取景是**设备无关**的（手机和平板开场看到同样宽的地面）；
   * 按层级则"每像素多少米"固定，屏幕越宽看到越多。
   */
  const settleScale = useMemo(() => {
    if (!ready) return 1;
    const bounds = basemap?.kind === 'tiles' ? basemap.bounds : null;
    if (settle.spanMeters !== null && bounds) {
      return clampScale(scaleForSpanMeters(settle.spanMeters, bounds, map?.initialView?.lng ?? 0, map?.initialView?.lat ?? 0, box, container), limits);
    }
    if (settle.zoom === null) return clampScale(settle.scale, limits);
    return clampScale(2 ** (settle.zoom - baseZoom), limits);
  }, [basemap, box, container, limits, map, ready, settle, baseZoom]);

  useEffect(() => {
    if (!ready) {
      setTransform(IDENTITY_TRANSFORM);
      return;
    }
    // 先比目标略微放大再回落，形成“推进来”的层次感；落位用的就是 settleScale。
    setTransform(clampTransform(centerOnPoint(settle.point, box, container, origin, settleScale * 1.15, limits), box, container, origin, limits));
    const frame = requestAnimationFrame(() => setTransform(clampTransform(centerOnPoint(settle.point, box, container, origin, settleScale, limits), box, container, origin, limits)));
    return () => cancelAnimationFrame(frame);
  }, [settle, settleScale, ready, box, container, origin, limits]);

  /** 「回到默认视野」：和进场用同一套落点，避免两处算法各写一遍。 */
  const applyDefaultView = useCallback(() => {
    if (!ready) return;
    setTransform(clampTransform(centerOnPoint(settle.point, box, container, origin, settleScale, limits), box, container, origin, limits));
  }, [box, container, limits, origin, ready, settle, settleScale]);

  /**
   * 关掉漫游层时把视野还给访客：进入漫游前做过一次「推进放大」，
   * 不还原的话会被留在放大 3 倍的位置上。
   * （深链直接进漫游时没有"进去之前"可言，此时 ref 为空，保持默认视野即可。）
   */
  useEffect(() => {
    if (roamId || !ready) return;
    const saved = preRoamTransform.current;
    if (!saved) return;
    preRoamTransform.current = null;
    setTransform(clampTransform(saved, box, container, origin, limits));
  }, [roamId, ready, box, container, origin, limits]);

  const applyZoom = useCallback((factor: number, focus: { x: number; y: number }) => {
    if (!ready) return;
    setTransform(current => clampTransform(zoomAtPoint(current, factor, focus, origin, limits), box, container, origin, limits));
  }, [box, container, origin, ready, limits]);

  const activate = useCallback((point: MapPointConfig) => {
    // 点选模式下，点地图是“在这里放标记”，不能顺带跳转。
    if (picking) return;
    /*
     * 全景并进了地图：漫游是这张地图的一层（`/map/:mapId/roam/:pointId`），
     * 作品在这一层的 iframe 中显示，返回按钮收起漫游层即可回到原来的地图视野。
     */
    const to = point.target.kind === 'panorama' && map
      ? `/map/${map.id}/roam/${point.target.id}`
      : targetRoute(point);
    if (!ready) {
      navigate(to);
      return;
    }
    setDrillingId(point.id);
    if (point.target.kind === 'map') {
      // 下钻到子地图：推进一点、停留一下，再切图（多层级配置时才会走到）。
      setTransform(clampTransform(centerOnPoint({ x: point.x, y: point.y }, box, container, origin, DRILL_SCALE, limits), box, container, origin, limits));
      drillTimer.current = window.setTimeout(() => {
        drillTimer.current = null;
        setDrillingId(null);
        navigate(to);
      }, DRILL_DURATION_MS);
      return;
    }
    /*
     * 进入全景/设备：做一段「渐进推进」——
     * 底图朝标记大幅放大，同时整屏压暗成幕布，切过去后由全景页把幕布淡出。
     * 比直接跳转更连贯，也让“我点的是这个地方”这件事看得见。
     * 进漫游前记住当前视野，关掉时原样还回去。
     */
    if (point.target.kind === 'panorama') preRoamTransform.current = transform;
    setEnteringId(point.id);
    setTransform(clampTransform(
      centerOnPoint({ x: point.x, y: point.y }, box, container, origin, Math.max(ENTER_SCALE, transform.scale * 3), limits),
      box, container, origin, limits,
    ));
    drillTimer.current = window.setTimeout(() => {
      drillTimer.current = null;
      setDrillingId(null);
      setEnteringId(null);
      navigate(`${to}?enter=1`);
    }, ENTER_DURATION_MS);
  }, [box, container, limits, map, navigate, picking, ready, transform.scale]);

  // 滚轮缩放：React 的 onWheel 在根节点上是被动监听，必须自己绑非被动监听才能 preventDefault。
  useEffect(() => {
    const stage = stageRef.current;
    if (!stage) return;
    const onWheel = (event: WheelEvent) => {
      event.preventDefault();
      const rect = stage.getBoundingClientRect();
      applyZoom(Math.exp(-event.deltaY * 0.0016), { x: event.clientX - rect.left, y: event.clientY - rect.top });
    };
    stage.addEventListener('wheel', onWheel, { passive: false });
    return () => stage.removeEventListener('wheel', onWheel);
  }, [applyZoom]);

  /**
   * 手势状态。注意：按下时不能立刻 setPointerCapture —— 指针被捕获后，浏览器会把随后的
   * click 事件重定向到捕获元素（也就是这个舞台容器），标记按钮的 onClick 就再也收不到了。
   * 因此只有移动超过阈值、确定是拖动/缩放时才捕获指针。
   */
  const gesture = useRef<{
    pointers: Map<number, { x: number; y: number }>;
    starts: Map<number, { x: number; y: number }>;
    base: MapTransform;
    distance: number;
    lastTap: number;
    captured: boolean;
  } | null>(null);

  const localPoint = (event: React.PointerEvent<HTMLDivElement>) => {
    const rect = event.currentTarget.getBoundingClientRect();
    return { x: event.clientX - rect.left, y: event.clientY - rect.top };
  };

  const capture = (event: React.PointerEvent<HTMLDivElement>, state: NonNullable<typeof gesture.current>) => {
    if (state.captured) return;
    state.captured = true;
    setDragging(true);
    try { event.currentTarget.setPointerCapture(event.pointerId); } catch { /* 部分内核不支持则退回普通事件流 */ }
  };

  const onPointerDown = (event: React.PointerEvent<HTMLDivElement>) => {
    if (!ready) return;
    const point = localPoint(event);
    const pointers = gesture.current?.pointers ?? new Map<number, { x: number; y: number }>();
    const starts = gesture.current?.starts ?? new Map<number, { x: number; y: number }>();
    pointers.set(event.pointerId, point);
    starts.set(event.pointerId, point);
    const [first, second] = [...pointers.values()];
    gesture.current = {
      pointers,
      starts,
      base: transform,
      distance: first && second ? Math.hypot(second.x - first.x, second.y - first.y) : 0,
      lastTap: gesture.current?.lastTap ?? 0,
      captured: gesture.current?.captured ?? false,
    };
    // 第二根手指落下就是缩放，可以直接捕获。
    if (pointers.size >= 2) capture(event, gesture.current);
  };

  const onPointerMove = (event: React.PointerEvent<HTMLDivElement>) => {
    const state = gesture.current;
    if (!state || !ready) return;
    const previous = state.pointers.get(event.pointerId);
    if (!previous) return;
    const next = localPoint(event);
    state.pointers.set(event.pointerId, next);

    if (!state.captured) {
      const start = state.starts.get(event.pointerId);
      const travelled = start ? Math.hypot(next.x - start.x, next.y - start.y) : 0;
      if (travelled < DRAG_THRESHOLD) return;
      capture(event, state);
    }

    const points = [...state.pointers.values()];
    const [first, second] = points;
    if (points.length >= 2 && first && second) {
      const distance = Math.hypot(second.x - first.x, second.y - first.y);
      if (state.distance > 0 && distance > 0) {
        const midpoint = { x: (first.x + second.x) / 2, y: (first.y + second.y) / 2 };
        setTransform(clampTransform(zoomAtPoint(state.base, distance / state.distance, midpoint, origin, limits), box, container, origin, limits));
      }
      return;
    }

    const delta = { x: next.x - previous.x, y: next.y - previous.y };
    setTransform(current => clampTransform({ scale: current.scale, x: current.x + delta.x, y: current.y + delta.y }, box, container, origin, limits));
  };

  const onPointerUp = (event: React.PointerEvent<HTMLDivElement>) => {
    const state = gesture.current;
    if (!state) return;
    const point = state.pointers.get(event.pointerId);
    state.pointers.delete(event.pointerId);
    state.starts.delete(event.pointerId);
    if (state.pointers.size > 0) return;

    setDragging(false);
    if (state.captured) {
      try { event.currentTarget.releasePointerCapture(event.pointerId); } catch { /* 未捕获时忽略 */ }
      state.captured = false;
      setTransform(current => clampTransform(current, box, container, origin, limits));
    } else if (point && event.pointerType !== 'mouse') {
      // 双击触屏放大：移动端没有滚轮，这是最顺手的放大方式（拖动过的手势不算点击）。
      const now = Date.now();
      if (now - state.lastTap < 320) {
        applyZoom(1.8, point);
        state.lastTap = 0;
      } else {
        state.lastTap = now;
      }
    }
    gesture.current = { ...state, pointers: new Map(), starts: new Map(), base: transform, distance: 0 };
  };

  /** 当前屏幕中心对应的经纬度 —— 就是「把当前视野设为默认」要保存的东西。 */
  const centerLngLat = useMemo(() => {
    if (basemap?.kind !== 'tiles' || !ready) return null;
    const view = visibleRect(transform, box, container, origin);
    const cx = Math.max(0, Math.min(1, (view.x0 + view.x1) / 2));
    const cy = Math.max(0, Math.min(1, (view.y0 + view.y1) / 2));
    return lngLatFromNormalized(cx, cy, basemap.bounds);
  }, [basemap, box, container, origin, ready, transform]);

  /** 当前画面横向覆盖多少米 —— 「设为默认视野」记的就是这个数（设备无关）。 */
  const visibleSpan = useMemo(() => {
    if (basemap?.kind !== 'tiles' || !ready || !centerLngLat) return null;
    const view = visibleRect(transform, box, container, origin);
    const width = Math.min(1, view.x1) - Math.max(0, view.x0);
    if (!(width > 0)) return null;
    return spanMetersOf(width, basemap.bounds, centerLngLat.lat);
  }, [basemap, box, centerLngLat, container, origin, ready, transform]);

  const mapOverrides: MapOverrides = draft.maps?.[map?.id ?? ''] ?? {};
  /** 草稿里的标记位置立即反映到地图上，不必等保存刷新。 */
  const displayPoints = useMemo(() => {
    if (!map) return [];
    const markers = mapOverrides.markers;
    if (!markers || basemap?.kind !== 'tiles') return map.points;
    return map.points.map(point => {
      const marker = markers[point.id];
      return marker ? { ...point, ...normalizeLngLat(marker.lng, marker.lat, basemap.bounds) } : point;
    });
  }, [basemap, map, mapOverrides.markers]);
  /** 面板里显示"武高所位置"要用**画面上那个**标记（草稿位置已即时生效），而不是配置里的旧值。 */
  const activeMarker = displayPoints[0] ?? map?.points[0];

  const updateMapOverrides = useCallback((patch: (current: MapOverrides) => MapOverrides) => {
    if (!map) return;
    setDraft(current => {
      const previous = current.maps?.[map.id] ?? {};
      return { ...current, version: 1, maps: { ...current.maps, [map.id]: patch(previous) } };
    });
  }, [map]);

  /** 导出成可以直接粘进 app/config/museum.json 的片段。 */
  const exportPatch = useMemo(() => {
    if (!map) return '{}';
    const view = mapOverrides.initialView;
    const markers = mapOverrides.markers ?? {};
    const points = map.points
      .flatMap(point => {
        const marker = markers[point.id];
        return marker ? [{ id: point.id, lng: marker.lng, lat: marker.lat }] : [];
      });
    const patch: Record<string, unknown> = {};
    if (draft.defaultRoute) patch.site = { defaultRoute: draft.defaultRoute };
    patch.maps = [{
      id: map.id,
      ...(view ? {
        initialView: {
          lng: view.lng,
          lat: view.lat,
          ...(view.spanMeters === undefined ? {} : { spanMeters: view.spanMeters }),
          ...(view.zoom === undefined ? {} : { zoom: view.zoom }),
        },
      } : {}),
      ...(points.length ? { points } : {}),
    }];
    return JSON.stringify(patch, null, 2);
  }, [draft.defaultRoute, map, mapOverrides.initialView, mapOverrides.markers]);

  const placeMarker = useCallback((clientX: number, clientY: number, pointId: string) => {
    const stage = stageRef.current;
    if (!stage || basemap?.kind !== 'tiles' || !ready) return;
    const rect = stage.getBoundingClientRect();
    const normalized = normalizedFromScreen({ x: clientX - rect.left, y: clientY - rect.top }, transform, box, origin);
    if (normalized.x < 0 || normalized.x > 1 || normalized.y < 0 || normalized.y > 1) {
      setNotice('这个位置已经在地图范围之外了');
      return;
    }
    const { lng, lat } = lngLatFromNormalized(normalized.x, normalized.y, basemap.bounds);
    updateMapOverrides(current => ({
      ...current,
      markers: { ...current.markers, [pointId]: { lng: Number(fixed(lng)), lat: Number(fixed(lat)) } },
    }));
    setPicking(null);
    setNotice('已移动标记，确认后点「保存并重新载入」');
  }, [basemap, box, origin, ready, transform, updateMapOverrides]);

  const downloadPatch = useCallback(() => {
    try {
      const blob = new Blob([exportPatch], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const anchor = document.createElement('a');
      anchor.href = url;
      anchor.download = 'museum-defaults.json';
      anchor.click();
      URL.revokeObjectURL(url);
    } catch { /* 不支持下载时下面的复制仍可用 */ }
    void navigator.clipboard?.writeText(exportPatch).then(
      () => setNotice('已复制配置片段，可直接粘进 app/config/museum.json'),
      () => setNotice('已下载 museum-defaults.json'),
    );
  }, [exportPatch]);

  if (!map) return <section className="status-panel" role="alert">没有可用的地图配置</section>;

  const parent = map.parentId ? repository.getMap(map.parentId) : undefined;
  const activePointId = focusId;
  const zoomHint = basemap?.kind === 'tiles'
    ? `z${zoom}（可自由缩放到 z${basemap.minZoom}~z${basemap.maxZoom}）`
    : `z${zoom}`;

  return (
    <section className={enteringId ? 'map-page is-entering' : 'map-page'}>
      <div className="map-topbar">
        {/*
          左上角只留地图名。
          原先这里还有一行小字（`map.level`，如"全域视角"）和一段描述文字（CSS 本就 display:none），
          都是噪音：标记上已经写着院区名字，说明也由底部提示承担。
          `map.level` 仍保留在配置里（面包屑与多级配置用得到），只是不再渲染。
        */}
        <header className="feature-hero map-hero">
          <h1>{map.name}</h1>
        </header>

        {path.length > 1 && (
          <nav className="map-crumbs" aria-label="地图层级">
            {path.map((item, index) => (
              <span key={item.id}>
                {index > 0 && <i aria-hidden="true">›</i>}
                {index === path.length - 1
                  ? <b aria-current="page">{item.name}</b>
                  : <button type="button" onClick={() => navigate(`/map/${item.id}`)}>{item.name}</button>}
              </span>
            ))}
          </nav>
        )}
      </div>

      <div
        className={[dragging ? 'map-stage is-dragging' : 'map-stage', picking ? 'is-picking' : ''].filter(Boolean).join(' ')}
        ref={stageRef}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        onPointerCancel={onPointerUp}
        onClick={event => {
          if (!picking || !activeMarker) return;
          placeMarker(event.clientX, event.clientY, picking);
        }}
        onDoubleClick={event => {
          if (picking) return;
          const rect = event.currentTarget.getBoundingClientRect();
          applyZoom(1.8, { x: event.clientX - rect.left, y: event.clientY - rect.top });
        }}
        data-testid="map-stage"
      >
        {/*
          图层几何用**布局尺寸**表达缩放，而不是 CSS scale：
          宽高直接写成「基准尺寸 × 倍数」，transform 只负责平移（scale 恒为 1）。
          Apple/WebKit 上把带 transform 的图层交给合成器缩放时，它会把这一层按当前栅格缓存成位图，
          之后缩放或动画收尾都只是把这张位图拉伸——高 DPR 的 iPhone 上就是"初始地图一进来就发虚"
          （WebKit 缩放上下文与合成层栅格化问题；`.map-layer` 去掉 will-change 也压不住 scale 本身）。
          瓦片本身按"源图 1:1"选层级（见 zoom 的 crispStep），只要不被合成器放大就是清晰的。
        */}
        <div
          className="map-layer"
          /* 基准宽与当前宽都取整到整像素：比例 `offsetWidth / data-base-width` 才能精确等于缩放倍数
             （不取整时 41652.7 : 41653 这种差 0.0003，e2e 里断言"缩到底正好 1 倍"就会挂）。 */
          data-base-width={Math.round(box.width)}
          style={{
            left: `${origin.x}px`,
            top: `${origin.y}px`,
            width: `${Math.round(box.width * transform.scale)}px`,
            height: `${Math.round(box.height * transform.scale)}px`,
            transform: `translate3d(${Math.round(transform.x)}px, ${Math.round(transform.y)}px, 0)`,
            transition: dragging
              ? 'none'
              : `transform ${enteringId ? ENTER_DURATION_MS - 120 : DRILL_DURATION_MS}ms cubic-bezier(.3,.05,.25,1)`,
          }}
        >
          {basemap?.kind === 'tiles'
            ? (
              <>
                {tiles.map(tile => {
                  // 瓦片尺寸落在**布局像素**上（1/256 的相对值 × 已放大的图层宽度），
                  // 布局尺寸没被任何变换放大，浏览器就会按设备像素把源图原样画出来。
                  const tileW = box.width * transform.scale * tile.width;
                  const tileH = box.height * transform.scale * tile.height;
                  return (
                    <TileImage
                      key={tile.key}
                      url={tile.url}
                      className={tile.overlay ? 'map-tile is-overlay' : 'map-tile'}
                      /* 钉住渲染尺寸的取整方向：宁可往外多铺 0.5px，也不要舍入后露出 0.5px 的缝
                         （瓦片之间的缝隙在高分屏上会被看成"发虚的白线"）。 */
                      style={{
                        left: `${Math.floor(box.width * transform.scale * tile.left)}px`,
                        top: `${Math.floor(box.height * transform.scale * tile.top)}px`,
                        width: `${Math.ceil(tileW)}px`,
                        height: `${Math.ceil(tileH)}px`,
                      }}
                    />
                  );
                })}
              </>
            )
            : (
              <img
                src={basemap ? resolveAssetUrl(basemap.image) : ''}
                alt={`${map.name}底图`}
                decoding="async"
                draggable={false}
                onLoad={event => setNatural({ width: event.currentTarget.naturalWidth, height: event.currentTarget.naturalHeight })}
              />
            )}
          {displayPoints.map(point => {
            // ?focus= 可能来自地图内部（点位 id），也可能来自全景页（目标 id）——两者都要能命中。
            const active = point.id === activePointId || point.target.id === activePointId;
            const drilling = point.id === drillingId;
            return (
              <button
                type="button"
                key={point.id}
                className={[`map-marker`, active ? 'is-active' : '', drilling ? 'is-drilling' : '', picking === point.id ? 'is-picking' : ''].filter(Boolean).join(' ')}
                style={{
                  left: `${point.x * 100}%`,
                  top: `${point.y * 100}%`,
                }}
                aria-label={markerLabel(point)}
                aria-pressed={active}
                onClick={() => activate(point)}
              >
                <i /><span>{point.label}</span>
              </button>
            );
          })}
        </div>

        <div className="map-controls">
          {settingsUnlocked && (
            <button
              type="button"
              className="map-settings-toggle"
              aria-label="地图设置"
              aria-expanded={settingsOpen}
              data-testid="map-settings-toggle"
              onClick={() => { setSettingsOpen(open => !open); setPicking(null); }}
            >
              <Settings size={18} />
            </button>
          )}
          <button type="button" aria-label="放大地图" onClick={() => applyZoom(1.6, { x: container.width / 2, y: container.height / 2 })}><Plus size={18} /></button>
          <button type="button" aria-label="缩小地图" onClick={() => applyZoom(1 / 1.6, { x: container.width / 2, y: container.height / 2 })}><Minus size={18} /></button>
          <button
            type="button"
            aria-label="回到默认视野"
            data-testid="map-reset-view"
            onClick={() => {
              // 连点 N 次解锁「地图设置」。这是给现场布展用的隐藏入口，访客不会碰到。
              if (!settingsUnlocked) {
                resetClicks.current += 1;
                if (resetClicks.current >= SETTINGS_UNLOCK_CLICKS) {
                  resetClicks.current = 0;
                  setSettingsUnlocked(true);
                  setNotice('已解锁「地图设置」（本次打开有效，刷新后重新隐藏）');
                } else if (resetClicks.current >= 2) {
                  setNotice(`再点 ${SETTINGS_UNLOCK_CLICKS - resetClicks.current} 次可打开地图设置`);
                }
              }
              const view = map.initialView;
              if (!view || basemap?.kind !== 'tiles') return;
              applyDefaultView();
            }}
          >
            <RotateCcw size={18} />
          </button>
        </div>
        {basemap?.kind === 'tiles' && <p className="map-attribution">{basemap.attribution}</p>}
      </div>

      {/* 进入全景前的幕布：与全景页的淡出用同一个颜色，接起来是一次连续推进。 */}
      <span className="map-veil" aria-hidden="true" />

      {picking && (
        <p className="map-pick-hint" role="status">
          <Crosshair size={15} />点按地图上院区所在的位置，放下标记
          <button type="button" onClick={() => setPicking(null)}>取消</button>
        </p>
      )}

      {settingsOpen && (
        <section className="map-settings" aria-label="地图设置" data-testid="map-settings">
          <header>
            <h2><Settings size={15} />地图设置</h2>
            <button type="button" aria-label="关闭设置" onClick={() => setSettingsOpen(false)}><X size={16} /></button>
          </header>

          <dl className="map-settings-view">
            <div>
              <dt>当前视野中心</dt>
              <dd>{centerLngLat ? `${fixed(centerLngLat.lng)}, ${fixed(centerLngLat.lat)}` : '—'}</dd>
            </div>
            <div>
              <dt>层级</dt>
              <dd>{zoomHint}</dd>
            </div>
            <div>
              <dt>武高所位置</dt>
              <dd data-testid="map-marker-position">
                {activeMarker && basemap?.kind === 'tiles'
                  ? (() => {
                    const geo = lngLatFromNormalized(activeMarker.x, activeMarker.y, basemap.bounds);
                    return `${fixed(geo.lng)}, ${fixed(geo.lat)}`;
                  })()
                  : '—'}
              </dd>
            </div>
          </dl>

          <div className="map-settings-actions">
            <button
              type="button"
              data-testid="map-set-default-view"
              disabled={!centerLngLat || !visibleSpan}
              onClick={() => {
                if (!centerLngLat || !visibleSpan) return;
                // 记下**横向跨度**而不是瓦片层级：这样换到任何屏幕、任何分辨率，
                // 开场看到的地面宽度都一致，院区的视觉大小也就一致。
                updateMapOverrides(current => ({
                  ...current,
                  initialView: {
                    lng: Number(fixed(centerLngLat.lng)),
                    lat: Number(fixed(centerLngLat.lat)),
                    spanMeters: Math.round(visibleSpan),
                  },
                }));
                setNotice(`已把当前视野设为默认（横向约 ${(visibleSpan / 1000).toFixed(1)} 公里）`);
              }}
            >
              把当前视野设为默认
            </button>
            <button
              type="button"
              data-testid="map-set-default-route"
              onClick={() => {
                setDraft(current => ({ ...current, version: 1, defaultRoute: `/map/${map.id}` }));
                setNotice('已设为默认打开页（保存后生效）');
              }}
            >
              设为默认打开页
            </button>
            <button
              type="button"
              data-testid="map-pick-marker"
              disabled={!activeMarker}
              className={picking ? 'is-active' : ''}
              onClick={() => { setPicking(picking ? null : activeMarker?.id ?? null); setSettingsOpen(false); }}
            >
              <Crosshair size={15} />在地图上点选位置
            </button>
          </div>

          <div className="map-settings-save">
            {canWriteConfig ? (
              <button
                type="button"
                className="is-primary"
                data-testid="map-write-config"
                disabled={saving}
                onClick={() => {
                  setSaving(true);
                  void writeConfigDefaults(JSON.parse(exportPatch)).then(result => {
                    setSaving(false);
                    if (!result.ok) {
                      setNotice(`写入配置失败：${result.error ?? '未知原因'}（已存本机）`);
                      saveOverrides(draft);
                      return;
                    }
                    // 已经落盘了，本机就不用再留一份覆盖，避免以后配置和本机设置两处不一致。
                    clearOverrides();
                    const skipped = result.skipped?.length ? `；跳过 ${result.skipped.join('、')}` : '';
                    setNotice(`已写入 app/config/museum.json${skipped}，正在重新载入…`);
                    window.setTimeout(reloadPage, 520);
                  });
                }}
              >
                <Save size={15} />{saving ? '正在写入…' : '保存到配置文件'}
              </button>
            ) : (
              <button
                type="button"
                className="is-primary"
                data-testid="map-save-settings"
                onClick={() => {
                  saveOverrides(draft);
                  setNotice('已保存到本机，正在重新载入…');
                  window.setTimeout(reloadPage, 260);
                }}
              >
                <Check size={15} />保存到本机并重新载入
              </button>
            )}
            <button type="button" data-testid="map-export-settings" onClick={downloadPatch}>
              <Download size={15} />导出片段
            </button>
            <button
              type="button"
              data-testid="map-hide-settings"
              onClick={() => {
                // 「隐藏设置」：收起面板并重新上锁，齿轮消失，需要再连点五次才能打开。
                setSettingsUnlocked(false);
                setSettingsOpen(false);
                setPicking(null);
                setNotice('已隐藏「地图设置」（连点 5 次「回到默认视野」可再次打开）');
              }}
            >
              <EyeOff size={15} />隐藏设置
            </button>
            <button
              type="button"
              data-testid="map-reset-settings"
              onClick={() => {
                clearOverrides();
                setDraft({ ...EMPTY_OVERRIDES });
                setNotice('已清除本机设置，正在重新载入…');
                window.setTimeout(reloadPage, 260);
              }}
            >
              <Trash2 size={15} />清除本机设置
            </button>
          </div>

          <p className="map-settings-note">
            {canWriteConfig
              ? <>点「保存到配置文件」会<b>直接写入</b> <code>app/config/museum.json</code>（开发服务器提供写回接口），刷新即生效。</>
              : <>当前不是开发服务器，浏览器改不了磁盘文件：设置先存在这台设备上，点「导出片段」再把内容写进 <code>app/config/museum.json</code>。</>}
          </p>
        </section>
      )}

      {notice && <p className="map-notice" role="status">{notice}</p>}

      {!settingsOpen && (
        <footer className="map-footer">
          {parent && <button type="button" className="map-back" onClick={() => navigate(`/map/${parent.id}`)}>返回{parent.name}</button>}
        </footer>
      )}

      {/*
        全景漫游：盖在地图之上的全屏层（不是另一个页面）。
        底下的地图保持挂载——关掉这层就回到原来的视野，瓦片也不用重新请求；
        底部导航始终高亮「全景漫游」。

        只在 active 时挂这一层：切入漫游的是第三方嵌入页（720yun），跨域 iframe 一旦挂上就会
        在后台继续跑（可能还有声音），没法暂停。本页被常驻槽位隐藏时先把它卸掉，
        地图本身（瓦片 + 视野）照旧保留——这是刻意的取舍，不是漏做。
      */}
      {roamId && active && (
        <div className="map-roam" data-testid="map-roam">
          <Suspense fallback={<p className="map-roam-loading">正在加载全景漫游</p>}>
            <PanoramaOverlay onExit={() => navigate(`/map/${map.id}`)} />
          </Suspense>
        </div>
      )}
    </section>
  );
}

export default MapPage;
